window.__finlexDocLoaded(10209,{"id":10209,"articles":[{"id":1000867,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Establishes recognition and disclosure rules for loss contingencies (ASC 450-20) and gain contingencies (ASC 450-30), using the higher US GAAP 'probable' threshold (~70%–75%+).","seq":0},{"id":1000868,"no":"ASC 450-20 / 450-30","heading":"Probable Threshold (~75%), Range Minimum & Gain Contingencies","text":"• Loss Contingency Recognition (ASC 450-20-25-2): Accrue when (a) probable (likely to occur, ~70%–75%+ in US practice) AND (b) reasonably estimable.\n• Range of Loss (ASC 450-20-30-1): If no point within a range is a better estimate than any other, accrue the MINIMUM amount in the range and disclose the upper bound.\n• Discounting: Generally prohibited unless amount and timing of cash payments are fixed or reliably determinable.\n• Gain Contingencies (ASC 450-30): Never recognized prior to realization.","seq":1},{"id":1000869,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Two Classic Divergences from IAS 37 / CAS 13: (1) Recognition threshold — ASC 450 'probable' (~70–75%+) is significantly higher than IAS 37 'more likely than not' (>50%); (2) Equal-probability range — ASC 450 accrues the MINIMUM of the range, whereas IAS 37 accrues the MIDPOINT (expected value for large populations).","seq":2},{"id":1000870,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
